  /**
   * After web form submit: desk-only lead + instant two-way session.
   * Uses deskForward — no visual workflow builder.
   */
  async sendFormConfirmation(submission) {
    return this.notifyFormSubmitted(submission);
  }

  async notifyFormSubmitted(tokenOrSubmission) {
    const submission =
      typeof tokenOrSubmission === 'string'
        ? Submissions.getByToken(tokenOrSubmission)
        : tokenOrSubmission;
    if (!submission) {
      console.warn('[WhatsApp] notifyFormSubmitted: submission not found');
      return false;
    }

    if (!AccessUsers.isUnlocked(submission.customer_phone)) {
      console.warn(
        `[WhatsApp] Form submit ignored — ${submission.customer_phone} not Active in access_users`
      );
      return false;
    }

    try {
      const result = await forwardLeadToDesk(this, submission, {
        phone: submission.customer_phone,
        chatId: submission.customer_chat_id || undefined,
        notifyCustomer: false,
        sendDeskTip: false,
      });
      console.log('[WhatsApp] Form → desk + two-way session:', result);
      return !!result?.ok;
    } catch (err) {
      console.error('[WhatsApp] Form → desk forward failed:', err.message);
      return false;
    }
  }

  async confirmAndForward(submission, opts = {}) {
    await forwardLeadToDesk(this, submission, {
      phone: submission.customer_phone,
      chatId: opts.chatId || submission.customer_chat_id,
      replyTo: opts.replyTo,
      inboundText: opts.inboundText,
      notifyCustomer: false,
      sendDeskTip: false,
    });
  }
}

